type":"ScriptedAction","script":"(function execute() {
 try {
 var r = new sn_ws.RESTMessageV2('Gemini', 'Query');
 r.setStringParameterNoEscape('prompt', vaInputs.get_you_question);
 var response = r.execute();
 var responseBody = response.getBody();
 var httpStatus = response.getStatusCode();

 if (httpStatus == '200') {
 var data = JSON.parse(responseBody);
 vaVars.gptAnswer = data.candidates[0].content.parts[0].text;
 } else {
 vaVars.gptAnswer = 'Error contacting Gemini: ' + httpStatus + ' - ' + responseBody;
 }
 } catch (ex) {
 vaVars.gptAnswer = 'Error: ' + ex.message;
 }
})();","id":"1e8fedfdba224516bd9772f4bd44c2e4","name":"call gemini","goal_id":"primary","applicability":{"type":"Applicability","mode":"script","value":"true"},"expert_mode":false},{"type":"TextOutputPrompt","value":[{"type":"String","mode":"script","value":"{{gptAnswer}}"}],"request_feedback":true,"isCollapsible":false,"id":"a71bfe3c78214e1ab9654ed9d34c7ff2","name":"Show Answer","goal_id":"primary","applicability":{"type":"Applicability","mode":"script","value":"true"},"expert_mode":false,"secure":false}],"edges":[{"type":"Edge","source_node_id":"a71bfe3c78214e1ab9654ed9d34c7ff2","target_node_id":"da170761b5cf45bb9e199fced83e15f6","id":"570480ef15da4eef8f68ee012eac9671"},{"type":"Edge","source_node_id":"4a7b8b697cf64b3f90e8a5b1707ae6ed","target_node_id":"da170761b5cf45bb9e199fced83e15f6","id":"00e70047892745eea6f44fd274b5813e"},{"type":"Edge","source_node_id":"da170761b5cf45bb9e199fced83e15f6","target_node_id":"71c2aea05d9a414cba2279167b78fad3","id":"86d9005bc6fb4ba1bda75feff964eace"},{"type":"Edge","source_node_id":"71c2aea05d9a414cba2279167b78fad3","target_node_id":"f0444220f1064dc7abb1c41db03d7e83","branch_id":"17a1ced056084243bedbf8888416a459","id":"0d8d2ee4364945f98edd55f4b47cd2f0","name":"17a1ced056084243bedbf8888416a459"},{"type":"Edge","source_node_id":"71c2aea05d9a414cba2279167b78fad3","target_node_id":"1e8fedfdba224516bd9772f4bd44c2e4","branch_id":"5112493671d14b23b658ee5adf58f64e","id":"3d47fb9cd4454dd3a169d51c2b08e7ad","name":"5112493671d14b23b658ee5adf58f64e"},{"type":"Edge","source_node_id":"1e8fedfdba224516bd9772f4bd44c2e4","target_node_id":"a71bfe3c78214e1ab9654ed9d34c7ff2","id":"26d2115e5f2d48889752c9ca6539eb04"}],"id":"primary"}],"script_variables":[{"type":"String","name":"gptAnswer","value":{"type":"String","mode":"string"},"list":false,"id":"e7458ed7e1fb49efad04af4413f66806","formatType":"text","secure":false,"sensitive":false,"aiInput":false}],"glide_variables":[{"type":"Reference","table":"sys_user","auto_select":false,"id":"current-user","na